    ".tano/objects/282f91.tano.json": "{\n  \"version\": 1,\n  \"id\": \"282f91\",\n  \"type\": \"event\",\n  \"name\": \"验收会议\",\n  \"description\": \"用于检查事件卡片与带时区的日期时间\",\n  \"archived\": false,\n  \"properties\": {\n    \"start\": \"2026-09-26T10:00:00+08:00\",\n    \"end\": \"2026-09-26T11:00:00+08:00\",\n    \"location\": \"本地测试\"\n  }\n}\n",
